type TranslationPairs = Array<[string, string]>;

const en = {
  short: "How to Use an ACBuy Spreadsheet",
  title: "How to Use an ACBuy Spreadsheet Without Losing the Product Trail",
  category: "Product discovery",
  keyword: "ACBuy spreadsheet",
  dek: "A spreadsheet is useful only when it connects a search idea to a current product record, a correctly submitted order and evidence from the warehouse. This guide explains that complete trail.",
  note: "This guide was checked against ACBuy’s current official homepage, shopping flow and product-order interface. The official flow describes link submission, domestic delivery to a designated warehouse, warehouse inspection, storage, parcel submission and international shipping. Variable prices, stock, seller terms and routes are deliberately not presented as fixed facts.",
  visual: ["Find a current record","Verify the exact variant","Submit the source link","Review warehouse evidence","Plan one parcel"],
  caption: "The spreadsheet is the starting index, not the final source of truth.",
};

export const article1Translations: Record<"de"|"fr"|"es"|"it"|"pl", TranslationPairs> = {
  de: [
    [en.short,"So nutzt du eine ACBuy-Tabelle"],[en.title,"So nutzt du eine ACBuy-Tabelle, ohne die Produktspur zu verlieren"],[en.category,"Produktsuche"],[en.keyword,"ACBuy-Tabelle"],[en.dek,"Eine Tabelle ist nur dann nützlich, wenn sie eine Suchidee mit einem aktuellen Produkteintrag, einer korrekt eingereichten Bestellung und Lagerbelegen verbindet. Dieser Leitfaden erklärt den gesamten Weg."],[en.note,"Dieser Leitfaden wurde anhand der aktuellen offiziellen ACBuy-Startseite, des Einkaufsablaufs und der Bestelloberfläche geprüft. Der offizielle Ablauf umfasst Linkeinreichung, Inlandsversand zum vorgesehenen Lager, Lagerprüfung, Aufbewahrung, Paketeinreichung und internationalen Versand. Veränderliche Preise, Bestände, Verkäuferbedingungen und Routen werden bewusst nicht als feste Fakten dargestellt."],
    [en.visual[0],"Aktuellen Eintrag finden"],[en.visual[1],"Genaue Variante prüfen"],[en.visual[2],"Quell-Link einreichen"],[en.visual[3],"Lagerbelege prüfen"],[en.visual[4],"Ein Paket planen"],[en.caption,"Die Tabelle ist der Startindex, nicht die endgültige Wahrheitsquelle."],
    ["Treat the spreadsheet as an index, not a shop","Tabelle als Index, nicht als Shop nutzen"],["People often open an ACBuy spreadsheet expecting it to behave like a normal online shop. That is the first mistake. A useful sheet is an organized discovery layer: it helps you move from a broad idea such as sneakers, hoodies or bags to a record that can be checked. The product page at the end of that trail matters more than the row in the sheet because seller stock, selectable variants, domestic delivery charges and listing details can change after the row was created.","Viele öffnen eine ACBuy-Tabelle wie einen normalen Onlineshop. Das ist der erste Fehler. Eine gute Tabelle ist eine geordnete Suchschicht: Sie führt von einer allgemeinen Idee wie Sneakern, Hoodies oder Taschen zu einem prüfbaren Eintrag. Die Produktseite am Ende ist wichtiger als die Tabellenzeile, weil Bestand, Varianten, Inlandsversand und Angebotsdetails sich später ändern können."],["The practical goal is therefore not to collect hundreds of links. It is to reduce uncertainty around a small number of products. A good row should give you enough context to identify the item, open the destination record and compare the current information. If a row contains only a picture and an attractive price, it is weak research. If it includes a clear product name, category, source identifier, current destination and a recent check date, it becomes a useful starting point.","Das Ziel ist nicht, Hunderte Links zu sammeln, sondern Unsicherheit bei wenigen Produkten zu verringern. Eine gute Zeile liefert genug Kontext, um den Artikel zu erkennen, den Zieleintrag zu öffnen und aktuelle Angaben zu vergleichen. Nur Bild und Lockpreis sind schwache Recherche; Produktname, Kategorie, Quell-ID, aktuelles Ziel und Prüfdatum ergeben einen brauchbaren Ausgangspunkt."],["Simple rule","Einfache Regel"],["Never make the final decision from the spreadsheet thumbnail or remembered price. Open the current destination record and inspect it again.","Treffe nie die endgültige Entscheidung anhand des Tabellenbilds oder eines gemerkten Preises. Öffne den aktuellen Zieleintrag und prüfe ihn erneut."],
    ["Start with a narrow search intention","Mit einer engen Suchabsicht beginnen"],["Broad searches create broad mistakes. Searching only for a brand name can return unrelated models, materials and price levels. A more useful query combines a product type with a feature: a zip hoodie, low-top shoe, nylon shoulder bag, embroidered jersey or heavyweight T-shirt. Model names, materials and intended use are also useful when they are genuinely part of the listing. This approach produces fewer results, but the remaining records are easier to compare and verify.","Breite Suchen erzeugen breite Fehler. Nur nach einer Marke zu suchen liefert oft unpassende Modelle, Materialien und Preisstufen. Besser ist Produkttyp plus Merkmal, etwa Zip-Hoodie, Low-Top-Schuh, Nylon-Umhängetasche, besticktes Trikot oder schweres T-Shirt. Echte Modellnamen, Materialien und Einsatzzwecke helfen ebenfalls. Es gibt weniger Ergebnisse, aber sie lassen sich besser vergleichen."],["Use categories for exploration and product records for confirmation. The category page answers the question, ‘What kinds of items are available?’ A product page answers narrower questions about the selected listing. Keep those two tasks separate. When several similar rows appear, compare source IDs and variants instead of assuming that similar pictures represent the same seller or product. Duplicate-looking images can lead to different offers, domestic shipping charges or after-sales conditions.","Kategorien dienen der Entdeckung, Produkteinträge der Bestätigung. Die Kategorie zeigt verfügbare Arten; die Produktseite beantwortet konkrete Fragen. Halte beide Aufgaben getrennt. Bei ähnlichen Zeilen vergleiche Quell-IDs und Varianten, statt gleiche Bilder mit demselben Verkäufer gleichzusetzen. Ähnliche Fotos können zu anderen Angeboten, Versandkosten oder After-Sales-Regeln führen."],["Search by product type, model or material.","Nach Produkttyp, Modell oder Material suchen."],["Open more than one plausible record before deciding.","Vor der Entscheidung mehrere plausible Einträge öffnen."],["Compare source IDs, variants and current seller information.","Quell-IDs, Varianten und aktuelle Verkäuferdaten vergleichen."],["Reject rows whose destination no longer matches the description.","Zeilen verwerfen, deren Ziel nicht mehr zur Beschreibung passt."],
    ["Verify the current product record","Aktuellen Produkteintrag prüfen"],["ACBuy’s current product interface makes an important distinction: products displayed for shopping-agent service come from third-party shopping platforms and are not directly sold by ACBuy. That means a listing should be read as a seller offer that the agent may help purchase, not as an ACBuy-owned product guarantee. Check the item title, visible specifications, minimum quantity, current price, seller information and available options. If the destination record has changed materially, the spreadsheet row is stale even if the link still opens.","Die aktuelle ACBuy-Oberfläche unterscheidet klar: Angezeigte Agentenprodukte stammen von Drittplattformen und werden nicht direkt von ACBuy verkauft. Lies das Angebot daher als Verkäuferangebot, das der Agent beschaffen kann, nicht als ACBuy-Produktgarantie. Prüfe Titel, sichtbare Spezifikationen, Mindestmenge, Preis, Verkäuferdaten und Optionen. Hat sich das Ziel wesentlich geändert, ist die Tabellenzeile veraltet, auch wenn der Link öffnet."],["Pay special attention to the exact variant. Color names can be ambiguous, size charts may use different units and a single page can contain several qualities or bundles. Save the source ID, selected option and a screenshot or note of the choice. This small record becomes valuable later when the warehouse photographs arrive. Without it, you may remember the general item but forget the exact color, included accessories or measurements you intended to receive.","Achte besonders auf die genaue Variante. Farbnamen können mehrdeutig sein, Größentabellen andere Einheiten nutzen und eine Seite mehrere Qualitäten oder Sets enthalten. Speichere Quell-ID, Auswahl und Screenshot oder Notiz. Das hilft später bei den Lagerfotos; sonst erinnerst du den Artikel, aber nicht Farbe, Zubehör oder erwartete Maße."],["What the record cannot prove","Was der Eintrag nicht beweist"],["A seller image cannot prove the condition of the physical item that will reach the warehouse. That evidence comes later from warehouse inspection.","Ein Verkäuferbild beweist nicht den Zustand des physischen Artikels im Lager. Dieser Beleg kommt erst mit der Lagerprüfung."],
    ["Understand the order form before paying","Bestellformular vor der Zahlung verstehen"],["The official ACBuy flow begins by pasting a product link and submitting an order. On a manual or third-party order form, required information can include the link, product name, specifications, remarks, unit price, quantity and domestic shipping fee. The interface also warns that international shipping is calculated separately. This separation matters: the product total and delivery to the Chinese warehouse are not the complete landed cost of receiving the parcel in another country.","Der offizielle ACBuy-Ablauf beginnt mit dem Einfügen eines Produktlinks und der Bestellung. Ein manuelles oder Drittanbieterformular kann Link, Produktname, Spezifikationen, Hinweise, Stückpreis, Menge und Inlandsversand verlangen. Internationaler Versand wird separat berechnet. Produktpreis plus Lieferung zum chinesischen Lager sind daher nicht die gesamten Kosten bis ins Zielland."],["Read every field as an instruction to the purchasing agent. Specifications should identify the exact option, while remarks should contain only information the seller or agent needs. Avoid vague notes such as ‘best quality’ because they are not measurable. A better note names a color code, size, bundle or visible feature. If the domestic delivery fee is uncertain, follow the current platform instructions rather than inventing a number. The agent may need to verify a charge before the order proceeds.","Lies jedes Feld als Anweisung an den Einkaufsagenten. Spezifikationen müssen die exakte Option nennen; Hinweise nur notwendige Informationen. Vage Wünsche wie „beste Qualität“ sind nicht messbar. Besser sind Farbcode, Größe, Set oder sichtbares Merkmal. Ist der Inlandsversand unklar, folge der aktuellen Plattformanweisung; der Agent muss die Gebühr möglicherweise bestätigen."],
    ["Build a warehouse evidence checkpoint","Lagerbelege als Prüfpunkt aufbauen"],["After the seller ships domestically, the item goes to ACBuy’s designated warehouse. The current official homepage describes warehouse quality inspection and lists three to five free QC photographs. It also advertises 90 days of free storage. These are current platform statements, not permanent promises, so the live account should be checked when an order arrives. The important habit is to stop treating the original listing as the only evidence once physical warehouse photographs exist.","Nach dem Inlandsversand gelangt der Artikel ins vorgesehene ACBuy-Lager. Die aktuelle offizielle Seite nennt eine Qualitätsprüfung, drei bis fünf kostenlose QC-Fotos und 90 Tage kostenlose Lagerung. Das sind aktuelle Angaben, keine dauerhaften Versprechen; prüfe sie bei Ankunft im Konto. Sobald Lagerfotos existieren, ist das ursprüngliche Angebot nicht mehr der einzige Beleg."],["Compare the warehouse item with the saved order record. Start with the selected color and model, then review quantity, obvious dimensions, included pieces, overall shape and visible damage. If a crucial detail is missing from the default views, investigate the platform’s current options for additional photographs or service requests before accepting the item. A spreadsheet can organize QC links or notes, but it should never replace looking carefully at the actual images.","Vergleiche den Lagerartikel mit dem gespeicherten Auftrag: Farbe, Modell, Menge, erkennbare Maße, Zubehör, Form und Schäden. Fehlt ein wichtiges Detail, prüfe aktuelle Optionen für Zusatzfotos oder Serviceanfragen, bevor du annimmst. Eine Tabelle kann QC-Links ordnen, ersetzt aber nie die sorgfältige Bildprüfung."],["Match the item to the saved source ID and variant.","Artikel mit gespeicherter Quell-ID und Variante abgleichen."],["Check the whole object before zooming into details.","Erst das ganze Objekt, dann Details prüfen."],["Record questions while return or exchange options may still be available.","Fragen notieren, solange Rückgabe oder Umtausch möglich sein können."],["Do not confuse a clean photograph with proof of material or durability.","Ein sauberes Foto nicht mit Material- oder Haltbarkeitsnachweis verwechseln."],
    ["Calculate the decision, not just the sticker price","Die Entscheidung berechnen, nicht nur den Preisschildwert"],["A low displayed item price can be attractive and still produce a poor purchase decision. The useful comparison includes the product price, domestic delivery to the warehouse, optional services, packaging choices and international shipping. Taxes or customs handling may also apply according to the destination and local rules. Because these variables are different for every parcel, a spreadsheet should not publish one universal ‘delivered price’ unless it clearly states the destination, date, route and assumptions.","Ein niedriger Artikelpreis kann dennoch eine schlechte Entscheidung ergeben. Vergleiche Produktpreis, Inlandsversand zum Lager, optionale Dienste, Verpackung und internationalen Versand; je nach Ziel kommen Steuern oder Zoll hinzu. Da jedes Paket anders ist, sollte eine Tabelle keinen universellen Endpreis nennen, ohne Ziel, Datum, Route und Annahmen auszuweisen."],["Use the listed price as one column in a larger decision. Bulky items may create volumetric weight; rigid packaging may protect shoes but enlarge the parcel; combining products can reduce repeated base charges but also change the available shipping lines. The official ACBuy flow promotes consolidation and parcel submission after storage, but the right parcel is not always the largest possible parcel. Wait for recorded warehouse data and compare the current estimator before submitting.","Nutze den Listenpreis nur als eine Spalte. Sperrige Artikel erzeugen Volumengewicht, starre Verpackung schützt Schuhe, vergrößert aber das Paket; Bündelung spart Grundgebühren, kann jedoch Routen ändern. Der passende Versand ist nicht immer das größte Paket. Warte auf Lagerdaten und vergleiche den aktuellen Rechner."],
    ["Keep a small audit trail","Kleine Prüfhistorie führen"],["The best spreadsheet workflow is surprisingly modest. For each serious candidate, keep the product name, destination URL, source ID, selected variant, observed price, check date and a short decision note. After purchase, add the order identifier, warehouse arrival date, QC result and parcel assignment. This turns a discovery list into a practical audit trail without filling it with personal payment information. It also makes it easier to explain a discrepancy to support because the original choice is documented.","Der beste Tabellenablauf bleibt klein. Speichere für jeden ernsthaften Kandidaten Produktname, Ziel-URL, Quell-ID, Variante, beobachteten Preis, Prüfdatum und kurze Notiz. Nach dem Kauf kommen Bestell-ID, Lagerankunft, QC-Ergebnis und Paketzuteilung hinzu. So entsteht eine praktische Historie ohne private Zahlungsdaten und Abweichungen lassen sich dem Support klarer erklären."],["Dates matter because agent platforms and third-party sellers are dynamic. A link checked three months ago is not equal to a link checked today. Stock can disappear, a seller can change variants, and a price can move. A responsible guide therefore shows when a record was reviewed and asks the reader to verify it again. That practice is more useful than claiming that every spreadsheet row is permanently safe, available or ‘best.’","Daten sind wichtig, weil Plattformen und Verkäufer dynamisch sind. Ein vor drei Monaten geprüfter Link ist nicht wie ein heutiger. Bestand, Varianten und Preise ändern sich. Ein verantwortlicher Leitfaden zeigt das Prüfdatum und fordert zur erneuten Kontrolle auf, statt jede Zeile dauerhaft als sicher, verfügbar oder „beste“ zu bezeichnen."],
    ["Use a repeatable five-step workflow","Wiederholbaren Fünf-Schritte-Ablauf nutzen"],["Begin with a narrow product search and shortlist only records that still match their descriptions. Second, open the current destination and document the exact variant, source ID and visible seller terms. Third, submit the source link through the current order form and review product price plus domestic delivery before payment. Fourth, compare the physical warehouse evidence with the saved order. Fifth, use actual warehouse data to decide which items belong in the same international parcel.","Beginne mit einer engen Suche und wähle nur passende Einträge. Öffne dann das aktuelle Ziel und dokumentiere Variante, Quell-ID und sichtbare Verkäuferbedingungen. Reiche den Link ein und prüfe Produktpreis plus Inlandsversand vor der Zahlung. Vergleiche danach Lagerbelege mit der Bestellung. Entscheide zuletzt anhand realer Lagerdaten, welche Artikel in dasselbe internationale Paket gehören."],["This sequence prevents the spreadsheet from becoming a substitute for judgment. It also aligns with the stages shown on ACBuy’s current official pages: place an order from a link, receive the item at the designated warehouse, inspect and store it, submit a parcel and select international shipping. The platform handles the shopping-agent workflow; your responsibility is to preserve the decision trail and recheck dynamic details at the moment they matter.","Diese Reihenfolge verhindert, dass die Tabelle eigenes Urteil ersetzt. Sie entspricht dem aktuellen ACBuy-Ablauf: per Link bestellen, im Lager empfangen, prüfen und lagern, Paket einreichen und internationalen Versand wählen. Die Plattform führt den Agentenprozess aus; du bewahrst die Entscheidungsspur und prüfst veränderliche Details im richtigen Moment."],
    ["Is an ACBuy spreadsheet an official product catalog?","Ist eine ACBuy-Tabelle ein offizieller Produktkatalog?"],["Not necessarily. This site is an independent discovery guide. Treat each row as a route to a current destination record and verify the seller listing before ordering.","Nicht unbedingt. Diese Seite ist ein unabhängiger Suchleitfaden. Nutze jede Zeile als Weg zum aktuellen Zieleintrag und prüfe das Verkäuferangebot."],["Why can the price in a sheet differ from the order page?","Warum kann der Tabellenpreis von der Bestellseite abweichen?"],["Third-party seller prices, variants, domestic delivery fees and availability can change. The live order page and agent verification take priority over an older spreadsheet value.","Preise, Varianten, Inlandsversand und Verfügbarkeit von Drittverkäufern können sich ändern. Die aktuelle Bestellseite und Agentenprüfung haben Vorrang."],["What should I save before submitting an order?","Was sollte ich vor der Bestellung speichern?"],["Keep the source ID or URL, exact variant, quantity, observed price and any measurable instruction. Do not store payment credentials in a shared sheet.","Speichere Quell-ID oder URL, Variante, Menge, beobachteten Preis und messbare Hinweise. Keine Zahlungsdaten in geteilten Tabellen speichern."],["Does a QC photo guarantee quality?","Garantiert ein QC-Foto Qualität?"],["No. It can show visible condition and selected features, but it cannot guarantee hidden construction, material composition, fit or long-term durability.","Nein. Es zeigt sichtbaren Zustand und Merkmale, garantiert aber keine verborgene Verarbeitung, Materialzusammensetzung, Passform oder Haltbarkeit."]
  ],
  fr: [
    [en.short,"Comment utiliser une feuille ACBuy"],[en.title,"Comment utiliser une feuille ACBuy sans perdre la trace du produit"],[en.category,"Découverte de produits"],[en.keyword,"feuille ACBuy"],[en.dek,"Une feuille n’est utile que si elle relie une recherche à une fiche actuelle, une commande correctement soumise et des preuves d’entrepôt. Ce guide suit tout le parcours."],[en.note,"Ce guide a été vérifié sur la page officielle actuelle d’ACBuy, son parcours d’achat et son interface de commande. Le processus couvre le lien source, la livraison nationale à l’entrepôt, le contrôle, le stockage, la soumission du colis et l’expédition internationale. Prix, stocks, conditions vendeur et lignes variables ne sont pas présentés comme fixes."],
    [en.visual[0],"Trouver une fiche actuelle"],[en.visual[1],"Vérifier la variante exacte"],[en.visual[2],"Soumettre le lien source"],[en.visual[3],"Contrôler les preuves d’entrepôt"],[en.visual[4],"Planifier un colis"],[en.caption,"La feuille est un index de départ, pas la source finale de vérité."],
    ["Treat the spreadsheet as an index, not a shop","Utiliser la feuille comme index, pas comme boutique"],["People often open an ACBuy spreadsheet expecting it to behave like a normal online shop. That is the first mistake. A useful sheet is an organized discovery layer: it helps you move from a broad idea such as sneakers, hoodies or bags to a record that can be checked. The product page at the end of that trail matters more than the row in the sheet because seller stock, selectable variants, domestic delivery charges and listing details can change after the row was created.","Beaucoup ouvrent une feuille ACBuy comme une boutique classique. C’est la première erreur. Une bonne feuille organise la découverte : elle mène d’une idée générale, comme baskets, sweats ou sacs, à une fiche vérifiable. La page produit finale compte davantage que la ligne, car stock, variantes, livraison nationale et détails peuvent changer."],["The practical goal is therefore not to collect hundreds of links. It is to reduce uncertainty around a small number of products. A good row should give you enough context to identify the item, open the destination record and compare the current information. If a row contains only a picture and an attractive price, it is weak research. If it includes a clear product name, category, source identifier, current destination and a recent check date, it becomes a useful starting point.","Le but n’est pas d’accumuler des centaines de liens, mais de réduire l’incertitude sur quelques produits. Une bonne ligne permet d’identifier l’article, d’ouvrir la fiche et de comparer les données actuelles. Image et prix séduisant seuls sont insuffisants ; nom, catégorie, identifiant source, destination et date de contrôle forment un vrai point de départ."],["Simple rule","Règle simple"],["Never make the final decision from the spreadsheet thumbnail or remembered price. Open the current destination record and inspect it again.","Ne décidez jamais depuis la miniature ou un ancien prix. Ouvrez la fiche de destination actuelle et contrôlez-la de nouveau."],
    ["Start with a narrow search intention","Commencer par une intention précise"],["Broad searches create broad mistakes. Searching only for a brand name can return unrelated models, materials and price levels. A more useful query combines a product type with a feature: a zip hoodie, low-top shoe, nylon shoulder bag, embroidered jersey or heavyweight T-shirt. Model names, materials and intended use are also useful when they are genuinely part of the listing. This approach produces fewer results, but the remaining records are easier to compare and verify.","Les recherches larges créent des erreurs larges. Une marque seule renvoie modèles, matières et prix sans rapport. Combinez type et caractéristique : sweat zippé, chaussure basse, sac nylon, maillot brodé ou T-shirt épais. Modèles, matières et usages réels aident aussi. Il reste moins de résultats, mais ils sont plus faciles à vérifier."],["Use categories for exploration and product records for confirmation. The category page answers the question, ‘What kinds of items are available?’ A product page answers narrower questions about the selected listing. Keep those two tasks separate. When several similar rows appear, compare source IDs and variants instead of assuming that similar pictures represent the same seller or product. Duplicate-looking images can lead to different offers, domestic shipping charges or after-sales conditions.","Utilisez les catégories pour explorer et les fiches pour confirmer. La catégorie montre les types disponibles ; la fiche répond aux questions précises. Si plusieurs lignes se ressemblent, comparez identifiants et variantes. Des images identiques peuvent mener à d’autres offres, frais nationaux ou conditions après-vente."],["Search by product type, model or material.","Rechercher par type, modèle ou matière."],["Open more than one plausible record before deciding.","Ouvrir plusieurs fiches plausibles avant de décider."],["Compare source IDs, variants and current seller information.","Comparer identifiants, variantes et vendeur actuel."],["Reject rows whose destination no longer matches the description.","Écarter les lignes dont la destination ne correspond plus."],
    ["Verify the current product record","Vérifier la fiche produit actuelle"],["ACBuy’s current product interface makes an important distinction: products displayed for shopping-agent service come from third-party shopping platforms and are not directly sold by ACBuy. That means a listing should be read as a seller offer that the agent may help purchase, not as an ACBuy-owned product guarantee. Check the item title, visible specifications, minimum quantity, current price, seller information and available options. If the destination record has changed materially, the spreadsheet row is stale even if the link still opens.","L’interface actuelle précise que les produits du service d’agent viennent de plateformes tierces et ne sont pas vendus directement par ACBuy. L’annonce est donc une offre vendeur que l’agent peut acheter, pas une garantie produit ACBuy. Vérifiez titre, caractéristiques, quantité minimale, prix, vendeur et options. Si la destination a changé, la ligne est obsolète même si le lien fonctionne."],["Pay special attention to the exact variant. Color names can be ambiguous, size charts may use different units and a single page can contain several qualities or bundles. Save the source ID, selected option and a screenshot or note of the choice. This small record becomes valuable later when the warehouse photographs arrive. Without it, you may remember the general item but forget the exact color, included accessories or measurements you intended to receive.","Contrôlez surtout la variante exacte. Les couleurs peuvent être ambiguës, les tailles utiliser d’autres unités et une page proposer plusieurs qualités ou lots. Enregistrez identifiant, option et capture ou note. Ces données seront utiles avec les photos d’entrepôt ; sans elles, vous risquez d’oublier couleur, accessoires ou mesures attendus."],["What the record cannot prove","Ce que la fiche ne prouve pas"],["A seller image cannot prove the condition of the physical item that will reach the warehouse. That evidence comes later from warehouse inspection.","Une image vendeur ne prouve pas l’état de l’article arrivé. Cette preuve vient du contrôle en entrepôt."],
    ["Understand the order form before paying","Comprendre le formulaire avant de payer"],["The official ACBuy flow begins by pasting a product link and submitting an order. On a manual or third-party order form, required information can include the link, product name, specifications, remarks, unit price, quantity and domestic shipping fee. The interface also warns that international shipping is calculated separately. This separation matters: the product total and delivery to the Chinese warehouse are not the complete landed cost of receiving the parcel in another country.","Le parcours officiel commence par le collage du lien et la commande. Un formulaire manuel ou tiers peut demander lien, nom, caractéristiques, remarques, prix, quantité et livraison nationale. L’expédition internationale est calculée séparément : produit et livraison à l’entrepôt chinois ne représentent pas le coût total dans le pays final."],["Read every field as an instruction to the purchasing agent. Specifications should identify the exact option, while remarks should contain only information the seller or agent needs. Avoid vague notes such as ‘best quality’ because they are not measurable. A better note names a color code, size, bundle or visible feature. If the domestic delivery fee is uncertain, follow the current platform instructions rather than inventing a number. The agent may need to verify a charge before the order proceeds.","Chaque champ est une instruction à l’agent. Les caractéristiques identifient l’option exacte et les remarques ne contiennent que l’utile. Évitez « meilleure qualité », impossible à mesurer ; indiquez code couleur, taille, lot ou détail visible. Si la livraison nationale est inconnue, suivez l’instruction actuelle : l’agent peut devoir vérifier le montant."],
    ["Build a warehouse evidence checkpoint","Créer un point de contrôle d’entrepôt"],["After the seller ships domestically, the item goes to ACBuy’s designated warehouse. The current official homepage describes warehouse quality inspection and lists three to five free QC photographs. It also advertises 90 days of free storage. These are current platform statements, not permanent promises, so the live account should be checked when an order arrives. The important habit is to stop treating the original listing as the only evidence once physical warehouse photographs exist.","Après l’envoi national, l’article arrive à l’entrepôt ACBuy. La page officielle actuelle décrit le contrôle qualité, trois à cinq photos QC gratuites et 90 jours de stockage gratuit. Ce sont des conditions actuelles, pas permanentes : vérifiez le compte à l’arrivée. Dès que les photos réelles existent, l’annonce d’origine n’est plus la seule preuve."],["Compare the warehouse item with the saved order record. Start with the selected color and model, then review quantity, obvious dimensions, included pieces, overall shape and visible damage. If a crucial detail is missing from the default views, investigate the platform’s current options for additional photographs or service requests before accepting the item. A spreadsheet can organize QC links or notes, but it should never replace looking carefully at the actual images.","Comparez l’article au dossier sauvegardé : couleur, modèle, quantité, dimensions visibles, pièces incluses, forme et dommages. Si un détail essentiel manque, vérifiez les options actuelles de photos ou services avant d’accepter. Une feuille peut organiser liens et notes QC, mais ne remplace pas l’examen des images."],["Match the item to the saved source ID and variant.","Comparer l’article à l’identifiant et à la variante sauvegardés."],["Check the whole object before zooming into details.","Contrôler l’ensemble avant les détails."],["Record questions while return or exchange options may still be available.","Noter les questions pendant que retour ou échange sont encore possibles."],["Do not confuse a clean photograph with proof of material or durability.","Ne pas confondre photo propre et preuve de matière ou durabilité."],
    ["Calculate the decision, not just the sticker price","Calculer la décision, pas seulement le prix"],["A low displayed item price can be attractive and still produce a poor purchase decision. The useful comparison includes the product price, domestic delivery to the warehouse, optional services, packaging choices and international shipping. Taxes or customs handling may also apply according to the destination and local rules. Because these variables are different for every parcel, a spreadsheet should not publish one universal ‘delivered price’ unless it clearly states the destination, date, route and assumptions.","Un prix bas peut conduire à une mauvaise décision. Comparez prix, livraison nationale, services, emballage et expédition internationale ; taxes ou douane peuvent s’ajouter. Chaque colis étant différent, une feuille ne doit pas annoncer un prix livré universel sans destination, date, ligne et hypothèses."],["Use the listed price as one column in a larger decision. Bulky items may create volumetric weight; rigid packaging may protect shoes but enlarge the parcel; combining products can reduce repeated base charges but also change the available shipping lines. The official ACBuy flow promotes consolidation and parcel submission after storage, but the right parcel is not always the largest possible parcel. Wait for recorded warehouse data and compare the current estimator before submitting.","Le prix affiché n’est qu’une colonne. Les articles volumineux créent du poids volumétrique, un emballage rigide protège mais agrandit, et le regroupement réduit certains frais tout en changeant les lignes disponibles. Le bon colis n’est pas toujours le plus gros. Attendez les données d’entrepôt et comparez l’estimateur actuel."],
    ["Keep a small audit trail","Conserver une petite piste de contrôle"],["The best spreadsheet workflow is surprisingly modest. For each serious candidate, keep the product name, destination URL, source ID, selected variant, observed price, check date and a short decision note. After purchase, add the order identifier, warehouse arrival date, QC result and parcel assignment. This turns a discovery list into a practical audit trail without filling it with personal payment information. It also makes it easier to explain a discrepancy to support because the original choice is documented.","Un bon suivi reste simple. Pour chaque candidat, gardez nom, URL, identifiant source, variante, prix observé, date et note. Après achat, ajoutez commande, arrivée, résultat QC et colis. La liste devient une piste utile sans données de paiement et permet d’expliquer une différence au support."],["Dates matter because agent platforms and third-party sellers are dynamic. A link checked three months ago is not equal to a link checked today. Stock can disappear, a seller can change variants, and a price can move. A responsible guide therefore shows when a record was reviewed and asks the reader to verify it again. That practice is more useful than claiming that every spreadsheet row is permanently safe, available or ‘best.’","Les dates comptent : plateformes et vendeurs changent. Un lien contrôlé il y a trois mois n’équivaut pas à un lien contrôlé aujourd’hui. Stock, variantes et prix évoluent. Un guide responsable affiche la date et demande une nouvelle vérification, au lieu de qualifier chaque ligne de sûre, disponible ou « meilleure » pour toujours."],
    ["Use a repeatable five-step workflow","Suivre cinq étapes répétables"],["Begin with a narrow product search and shortlist only records that still match their descriptions. Second, open the current destination and document the exact variant, source ID and visible seller terms. Third, submit the source link through the current order form and review product price plus domestic delivery before payment. Fourth, compare the physical warehouse evidence with the saved order. Fifth, use actual warehouse data to decide which items belong in the same international parcel.","Commencez par une recherche précise et ne gardez que les fiches encore conformes. Ouvrez la destination, notez variante, identifiant et conditions visibles. Soumettez le lien et contrôlez prix plus livraison nationale. Comparez ensuite les preuves d’entrepôt à la commande. Enfin, utilisez les données réelles pour composer le colis international."],["This sequence prevents the spreadsheet from becoming a substitute for judgment. It also aligns with the stages shown on ACBuy’s current official pages: place an order from a link, receive the item at the designated warehouse, inspect and store it, submit a parcel and select international shipping. The platform handles the shopping-agent workflow; your responsibility is to preserve the decision trail and recheck dynamic details at the moment they matter.","Cette séquence empêche la feuille de remplacer le jugement. Elle suit le parcours ACBuy actuel : commander par lien, recevoir, contrôler et stocker, soumettre un colis puis choisir l’expédition. La plateforme gère le service d’agent ; vous conservez la piste de décision et revérifiez les données variables au bon moment."],
    ["Is an ACBuy spreadsheet an official product catalog?","Une feuille ACBuy est-elle un catalogue officiel ?"],["Not necessarily. This site is an independent discovery guide. Treat each row as a route to a current destination record and verify the seller listing before ordering.","Pas nécessairement. Ce site est un guide indépendant. Chaque ligne mène à une fiche actuelle qu’il faut vérifier avant commande."],["Why can the price in a sheet differ from the order page?","Pourquoi le prix diffère-t-il de la page de commande ?"],["Third-party seller prices, variants, domestic delivery fees and availability can change. The live order page and agent verification take priority over an older spreadsheet value.","Prix vendeur, variantes, livraison nationale et disponibilité changent. La page en direct et la vérification de l’agent priment."],["What should I save before submitting an order?","Que faut-il sauvegarder avant de commander ?"],["Keep the source ID or URL, exact variant, quantity, observed price and any measurable instruction. Do not store payment credentials in a shared sheet.","Gardez identifiant ou URL, variante, quantité, prix observé et instruction mesurable. Ne stockez pas de données de paiement dans une feuille partagée."],["Does a QC photo guarantee quality?","Une photo QC garantit-elle la qualité ?"],["No. It can show visible condition and selected features, but it cannot guarantee hidden construction, material composition, fit or long-term durability.","Non. Elle montre l’état visible et certains détails, mais ne garantit ni construction cachée, ni matière, ni coupe, ni durabilité."]
  ],
  es: [],
  it: [],
  pl: [],
};

function attach(locale: "es"|"it"|"pl", values: string[]) {
  if (values.length !== article1Translations.de.length) throw new Error(`Article 1 ${locale} translation count mismatch`);
  article1Translations[locale] = article1Translations.de.map(([source], index) => [source, values[index]]);
}

attach("es", [
  "Cómo usar una hoja de ACBuy","Cómo usar una hoja de ACBuy sin perder el rastro del producto","Descubrimiento de productos","hoja de ACBuy",
  "Una hoja solo sirve si conecta una búsqueda con una ficha actual, un pedido correctamente enviado y pruebas del almacén. Esta guía explica todo el recorrido.",
  "Esta guía se comprobó con la página oficial actual de ACBuy, su proceso de compra y la interfaz de pedido. El flujo incluye envío del enlace, entrega nacional al almacén, inspección, almacenamiento, creación del paquete y envío internacional. Los precios, existencias, condiciones del vendedor y rutas variables no se presentan como datos fijos.",
  "Encontrar una ficha actual","Verificar la variante exacta","Enviar el enlace de origen","Revisar pruebas del almacén","Planificar un paquete","La hoja es el índice inicial, no la fuente definitiva.",
  "Usa la hoja como índice, no como tienda",
  "Mucha gente abre una hoja de ACBuy como si fuera una tienda normal. Ese es el primer error. Una buena hoja organiza el descubrimiento: lleva de una idea amplia, como zapatillas, sudaderas o bolsos, a una ficha verificable. La página final importa más que la fila porque stock, variantes, envío nacional y detalles pueden cambiar.",
  "El objetivo no es reunir cientos de enlaces, sino reducir la incertidumbre sobre pocos productos. Una buena fila permite identificar el artículo, abrir la ficha y comparar datos actuales. Una foto y un precio atractivo son una investigación débil; nombre, categoría, ID de origen, destino y fecha de revisión forman un punto de partida útil.",
  "Regla sencilla","Nunca decidas por la miniatura o un precio recordado. Abre la ficha actual y revísala de nuevo.",
  "Empieza con una intención de búsqueda precisa",
  "Las búsquedas amplias generan errores amplios. Buscar solo una marca devuelve modelos, materiales y precios distintos. Es mejor combinar tipo y característica: sudadera con cremallera, zapatilla baja, bolso de nailon, camiseta bordada o camiseta gruesa. Los modelos, materiales y usos reales también ayudan. Habrá menos resultados, pero serán más fáciles de comparar.",
  "Usa categorías para explorar y fichas para confirmar. La categoría muestra qué tipos existen; la ficha responde preguntas concretas. Si varias filas se parecen, compara IDs y variantes. Imágenes iguales pueden conducir a vendedores, gastos nacionales o condiciones posventa diferentes.",
  "Busca por tipo de producto, modelo o material.","Abre varias fichas plausibles antes de decidir.","Compara IDs de origen, variantes y datos actuales del vendedor.","Descarta filas cuyo destino ya no coincida con la descripción.",
  "Verifica la ficha de producto actual",
  "La interfaz actual de ACBuy aclara que los productos del servicio de agente proceden de plataformas de terceros y no los vende directamente ACBuy. La ficha es una oferta del vendedor que el agente puede comprar, no una garantía de producto de ACBuy. Comprueba título, especificaciones visibles, cantidad mínima, precio, vendedor y opciones. Si el destino cambió de forma importante, la fila está obsoleta aunque el enlace abra.",
  "Presta especial atención a la variante. Los nombres de color pueden ser ambiguos, las tallas usar otras unidades y una página incluir varias calidades o lotes. Guarda ID, opción y captura o nota. Será útil cuando lleguen las fotos del almacén; sin ello puedes olvidar color, accesorios o medidas exactas.",
  "Lo que la ficha no puede demostrar","Una imagen del vendedor no demuestra el estado del artículo físico que llegará al almacén. Esa prueba aparece con la inspección.",
  "Comprende el formulario antes de pagar",
  "El flujo oficial comienza pegando un enlace y enviando el pedido. Un formulario manual o de terceros puede pedir enlace, nombre, especificaciones, notas, precio unitario, cantidad y envío nacional. El envío internacional se calcula aparte: producto y entrega al almacén chino no son el coste total hasta otro país.",
  "Lee cada campo como una instrucción al agente. Las especificaciones deben identificar la opción exacta y las notas contener solo lo necesario. Evita frases vagas como «mejor calidad»; indica código de color, talla, lote o rasgo visible. Si el envío nacional no está claro, sigue la instrucción actual y deja que el agente verifique el cargo.",
  "Crea un punto de control con pruebas del almacén",
  "Tras el envío nacional, el artículo llega al almacén designado. La página oficial actual describe inspección, tres a cinco fotos QC gratuitas y 90 días de almacenamiento gratuito. Son condiciones actuales, no promesas permanentes; compruébalas en la cuenta. Cuando existen fotos físicas, la oferta original deja de ser la única prueba.",
  "Compara el artículo con el pedido guardado: color, modelo, cantidad, medidas visibles, piezas, forma y daños. Si falta un detalle esencial, revisa opciones actuales de fotos o servicio antes de aceptar. La hoja organiza enlaces y notas QC, pero no sustituye mirar las imágenes.",
  "Relaciona el artículo con el ID y la variante guardados.","Comprueba el objeto completo antes de ampliar detalles.","Anota preguntas mientras aún pueda haber devolución o cambio.","No confundas una foto limpia con prueba de material o durabilidad.",
  "Calcula la decisión, no solo el precio",
  "Un precio bajo puede acabar en una mala compra. Compara precio, envío nacional, servicios, embalaje e internacional; también pueden aplicarse impuestos o aduanas. Cada paquete es distinto, así que una hoja no debe publicar un precio entregado universal sin destino, fecha, ruta y supuestos.",
  "El precio mostrado es solo una columna. Los artículos voluminosos generan peso dimensional, una caja rígida protege pero agranda y consolidar reduce cargos base aunque puede cambiar rutas. El paquete correcto no siempre es el mayor. Espera los datos del almacén y compara el estimador actual.",
  "Conserva un pequeño historial",
  "Un buen flujo de hoja es sencillo. Guarda nombre, URL, ID de origen, variante, precio observado, fecha y nota. Tras comprar, añade ID de pedido, llegada, resultado QC y paquete. Así obtienes un historial práctico sin datos de pago y puedes explicar diferencias al soporte.",
  "Las fechas importan porque plataformas y vendedores cambian. Un enlace revisado hace tres meses no equivale a uno revisado hoy. Stock, variantes y precio pueden variar. Una guía responsable muestra la fecha y pide verificar de nuevo, en vez de declarar cada fila segura, disponible o «mejor» para siempre.",
  "Sigue un proceso repetible de cinco pasos",
  "Empieza con una búsqueda precisa y conserva solo fichas que aún coincidan. Abre el destino y documenta variante, ID y condiciones visibles. Envía el enlace y revisa precio más envío nacional. Compara después las pruebas del almacén con el pedido. Por último, usa datos reales para decidir qué artículos van juntos.",
  "Esta secuencia evita que la hoja sustituya el criterio. Sigue el flujo actual de ACBuy: pedir por enlace, recibir, inspeccionar y almacenar, enviar el paquete y elegir transporte internacional. La plataforma gestiona el agente; tú conservas el rastro de la decisión y vuelves a comprobar los datos variables.",
  "¿Una hoja de ACBuy es un catálogo oficial?","No necesariamente. Este sitio es una guía independiente. Usa cada fila como camino a una ficha actual y verifica la oferta antes de pedir.",
  "¿Por qué el precio de la hoja puede diferir del pedido?","Precios, variantes, envío nacional y disponibilidad de terceros cambian. La página en vivo y la verificación del agente tienen prioridad.",
  "¿Qué debo guardar antes de enviar el pedido?","Guarda ID o URL, variante exacta, cantidad, precio observado e instrucciones medibles. No guardes credenciales de pago en una hoja compartida.",
  "¿Una foto QC garantiza la calidad?","No. Muestra estado visible y algunos rasgos, pero no garantiza construcción oculta, composición, ajuste o durabilidad."
]);

attach("it", [
  "Come usare un foglio ACBuy","Come usare un foglio ACBuy senza perdere la traccia del prodotto","Scoperta dei prodotti","foglio ACBuy",
  "Un foglio è utile solo se collega una ricerca a una scheda attuale, un ordine inviato correttamente e prove dal magazzino. Questa guida segue l’intero percorso.",
  "La guida è stata verificata sulla pagina ufficiale attuale di ACBuy, nel flusso di acquisto e nell’interfaccia d’ordine. Il processo comprende invio del link, consegna nazionale al magazzino, controllo, deposito, creazione del pacco e spedizione internazionale. Prezzi, scorte, condizioni del venditore e rotte variabili non sono presentati come fissi.",
  "Trova una scheda attuale","Verifica la variante esatta","Invia il link sorgente","Controlla le prove di magazzino","Pianifica un pacco","Il foglio è l’indice iniziale, non la fonte definitiva.",
  "Usa il foglio come indice, non come negozio",
  "Molti aprono un foglio ACBuy come un normale negozio online. È il primo errore. Un buon foglio organizza la scoperta: porta da un’idea ampia, come sneakers, felpe o borse, a una scheda verificabile. La pagina finale conta più della riga perché scorte, varianti, spedizione nazionale e dettagli possono cambiare.",
  "Lo scopo non è raccogliere centinaia di link, ma ridurre l’incertezza su pochi prodotti. Una buona riga permette di identificare l’articolo, aprire la scheda e confrontare dati attuali. Solo foto e prezzo attraente sono ricerca debole; nome, categoria, ID sorgente, destinazione e data di controllo formano un buon punto di partenza.",
  "Regola semplice","Non decidere mai dalla miniatura o da un prezzo ricordato. Apri la scheda attuale e controllala di nuovo.",
  "Parti da un intento di ricerca preciso",
  "Le ricerche ampie producono errori ampi. Cercare solo un marchio restituisce modelli, materiali e prezzi diversi. Meglio combinare tipo e caratteristica: felpa con zip, scarpa bassa, borsa in nylon, maglia ricamata o T-shirt pesante. Modelli, materiali e usi reali aiutano. I risultati saranno meno numerosi ma più facili da verificare.",
  "Usa le categorie per esplorare e le schede per confermare. La categoria mostra i tipi disponibili; la pagina prodotto risponde a domande precise. Se più righe sembrano uguali, confronta ID e varianti. Immagini simili possono portare a venditori, costi nazionali o condizioni post-vendita differenti.",
  "Cerca per tipo di prodotto, modello o materiale.","Apri più schede plausibili prima di decidere.","Confronta ID sorgente, varianti e dati attuali del venditore.","Scarta le righe la cui destinazione non corrisponde più.",
  "Verifica la scheda prodotto attuale",
  "L’interfaccia attuale ACBuy chiarisce che i prodotti del servizio agente provengono da piattaforme terze e non sono venduti direttamente da ACBuy. La scheda è quindi un’offerta del venditore che l’agente può acquistare, non una garanzia ACBuy. Controlla titolo, specifiche, quantità minima, prezzo, venditore e opzioni. Se la destinazione è cambiata, la riga è vecchia anche se il link funziona.",
  "Controlla con attenzione la variante. I colori possono essere ambigui, le tabelle taglie usare unità diverse e una pagina contenere più qualità o set. Salva ID, opzione e screenshot o nota. Servirà quando arrivano le foto; senza potresti dimenticare colore, accessori o misure esatte.",
  "Cosa non prova la scheda","L’immagine del venditore non prova lo stato dell’articolo fisico che arriverà. La prova viene dal controllo in magazzino.",
  "Comprendi il modulo prima di pagare",
  "Il flusso ufficiale inizia incollando un link e inviando l’ordine. Un modulo manuale o terzo può richiedere link, nome, specifiche, note, prezzo, quantità e spedizione nazionale. La spedizione internazionale è separata: prodotto e consegna al magazzino cinese non sono il costo totale fino al paese finale.",
  "Leggi ogni campo come un’istruzione all’agente. Le specifiche identificano l’opzione esatta e le note contengono solo ciò che serve. Evita frasi vaghe come «qualità migliore»; indica codice colore, taglia, set o caratteristica visibile. Se la spedizione nazionale è incerta, segui l’istruzione attuale e lascia verificare il costo all’agente.",
  "Crea un controllo basato sulle prove di magazzino",
  "Dopo la spedizione nazionale, l’articolo arriva al magazzino designato. La pagina ufficiale attuale descrive controllo, tre-cinque foto QC gratuite e 90 giorni di deposito gratuito. Sono condizioni attuali, non promesse permanenti; verificale nell’account. Quando esistono foto fisiche, l’offerta originale non è più l’unica prova.",
  "Confronta l’articolo con l’ordine salvato: colore, modello, quantità, misure visibili, pezzi, forma e danni. Se manca un dettaglio importante, controlla le opzioni attuali per foto o servizi prima di accettare. Il foglio organizza link e note QC, ma non sostituisce l’esame delle immagini.",
  "Abbina l’articolo all’ID e alla variante salvati.","Controlla l’oggetto intero prima dei dettagli.","Annota domande mentre reso o cambio possono essere disponibili.","Non confondere una foto pulita con prova di materiale o durata.",
  "Calcola la decisione, non solo il prezzo",
  "Un prezzo basso può comunque portare a un cattivo acquisto. Confronta prezzo, spedizione nazionale, servizi, imballaggio e spedizione internazionale; possono aggiungersi tasse o dogana. Ogni pacco è diverso, quindi un foglio non deve pubblicare un prezzo consegnato universale senza destinazione, data, rotta e ipotesi.",
  "Il prezzo indicato è solo una colonna. Articoli voluminosi generano peso dimensionale, imballaggi rigidi proteggono ma ingrandiscono e il consolidamento riduce costi base ma può cambiare le rotte. Il pacco giusto non è sempre il più grande. Attendi i dati del magazzino e confronta il calcolatore attuale.",
  "Conserva una piccola traccia di controllo",
  "Un buon flusso resta semplice. Salva nome, URL, ID sorgente, variante, prezzo osservato, data e nota. Dopo l’acquisto aggiungi ID ordine, arrivo, risultato QC e pacco. Ottieni una traccia utile senza dati di pagamento e puoi spiegare meglio le differenze all’assistenza.",
  "Le date contano perché piattaforme e venditori cambiano. Un link controllato tre mesi fa non equivale a uno controllato oggi. Scorte, varianti e prezzi variano. Una guida responsabile mostra la data e chiede una nuova verifica, invece di dichiarare ogni riga sempre sicura, disponibile o «migliore».",
  "Segui cinque passaggi ripetibili",
  "Inizia con una ricerca precisa e conserva solo schede ancora coerenti. Apri la destinazione e documenta variante, ID e condizioni visibili. Invia il link e controlla prezzo più spedizione nazionale. Confronta poi le prove di magazzino con l’ordine. Infine usa dati reali per decidere quali articoli spedire insieme.",
  "Questa sequenza impedisce al foglio di sostituire il giudizio. Segue il flusso ACBuy attuale: ordine da link, ricezione, controllo e deposito, invio del pacco e scelta della spedizione internazionale. La piattaforma gestisce il servizio agente; tu conservi la traccia e ricontrolli i dati variabili.",
  "Un foglio ACBuy è un catalogo ufficiale?","Non necessariamente. Questo sito è una guida indipendente. Usa ogni riga come percorso verso una scheda attuale e verifica l’offerta.",
  "Perché il prezzo del foglio può differire dall’ordine?","Prezzi, varianti, spedizione nazionale e disponibilità dei venditori possono cambiare. La pagina live e la verifica dell’agente hanno priorità.",
  "Cosa devo salvare prima di inviare un ordine?","Conserva ID o URL, variante esatta, quantità, prezzo osservato e istruzioni misurabili. Non salvare credenziali di pagamento in un foglio condiviso.",
  "Una foto QC garantisce la qualità?","No. Mostra stato visibile e alcune caratteristiche, ma non garantisce costruzione nascosta, composizione, vestibilità o durata."
]);

attach("pl", [
  "Jak korzystać z arkusza ACBuy","Jak korzystać z arkusza ACBuy bez utraty śladu produktu","Wyszukiwanie produktów","arkusz ACBuy",
  "Arkusz jest użyteczny tylko wtedy, gdy łączy wyszukiwanie z aktualnym wpisem, prawidłowo złożonym zamówieniem i dowodami z magazynu. Ten poradnik pokazuje całą drogę.",
  "Poradnik sprawdzono z aktualną oficjalną stroną ACBuy, procesem zakupowym i interfejsem zamówienia. Proces obejmuje przesłanie linku, dostawę krajową do magazynu, kontrolę, przechowanie, utworzenie paczki i wysyłkę międzynarodową. Zmienne ceny, stany, warunki sprzedawcy i trasy nie są przedstawiane jako stałe fakty.",
  "Znajdź aktualny wpis","Sprawdź dokładny wariant","Prześlij link źródłowy","Sprawdź dowody magazynowe","Zaplanuj paczkę","Arkusz jest indeksem początkowym, a nie ostatecznym źródłem prawdy.",
  "Traktuj arkusz jak indeks, nie sklep",
  "Wiele osób otwiera arkusz ACBuy jak zwykły sklep internetowy. To pierwszy błąd. Dobry arkusz porządkuje odkrywanie: prowadzi od ogólnego pomysłu, np. butów, bluz czy toreb, do wpisu możliwego do sprawdzenia. Końcowa karta produktu jest ważniejsza niż wiersz, bo stan, warianty, dostawa krajowa i szczegóły mogą się zmienić.",
  "Celem nie jest zbieranie setek linków, lecz zmniejszenie niepewności wokół kilku produktów. Dobry wiersz pozwala rozpoznać artykuł, otworzyć wpis i porównać aktualne dane. Sam obraz i atrakcyjna cena to słaba analiza; nazwa, kategoria, ID źródła, cel i data kontroli tworzą użyteczny punkt startowy.",
  "Prosta zasada","Nie podejmuj ostatecznej decyzji na podstawie miniatury lub zapamiętanej ceny. Otwórz aktualny wpis i sprawdź go ponownie.",
  "Zacznij od precyzyjnego zamiaru wyszukiwania",
  "Szerokie wyszukiwanie daje szerokie błędy. Sama marka zwraca różne modele, materiały i ceny. Lepiej połączyć typ z cechą: bluza z zamkiem, niskie buty, nylonowa torba, haftowana koszulka czy ciężki T-shirt. Prawdziwe nazwy modeli, materiały i zastosowanie też pomagają. Wyników jest mniej, ale łatwiej je porównać.",
  "Kategorie służą do odkrywania, a karty do potwierdzania. Kategoria pokazuje dostępne typy, karta odpowiada na szczegółowe pytania. Przy podobnych wierszach porównuj ID i warianty. Podobne zdjęcia mogą prowadzić do innych ofert, kosztów krajowych lub zasad posprzedażowych.",
  "Szukaj według typu, modelu lub materiału.","Przed decyzją otwórz więcej niż jeden pasujący wpis.","Porównaj ID źródła, warianty i aktualne dane sprzedawcy.","Odrzuć wiersze, których cel nie pasuje już do opisu.",
  "Sprawdź aktualny wpis produktu",
  "Obecny interfejs ACBuy wyjaśnia, że produkty usługi agenta pochodzą z platform zewnętrznych i nie są sprzedawane bezpośrednio przez ACBuy. Wpis to oferta sprzedawcy, którą agent może kupić, a nie gwarancja produktu ACBuy. Sprawdź tytuł, specyfikację, minimum, cenę, sprzedawcę i opcje. Jeśli cel istotnie się zmienił, wiersz jest nieaktualny mimo działającego linku.",
  "Zwróć uwagę na dokładny wariant. Nazwy kolorów bywają niejasne, tabele rozmiarów używają różnych jednostek, a jedna strona może zawierać kilka jakości lub zestawów. Zapisz ID, opcję i zrzut lub notatkę. Przyda się przy zdjęciach magazynowych; bez tego łatwo zapomnieć kolor, akcesoria lub oczekiwane wymiary.",
  "Czego wpis nie potwierdza","Zdjęcie sprzedawcy nie potwierdza stanu fizycznego artykułu, który dotrze do magazynu. Dowód pojawia się podczas kontroli magazynowej.",
  "Zrozum formularz przed płatnością",
  "Oficjalny proces zaczyna się od wklejenia linku i złożenia zamówienia. Formularz może wymagać linku, nazwy, specyfikacji, uwag, ceny, ilości i dostawy krajowej. Wysyłka międzynarodowa jest liczona osobno: produkt i dowóz do magazynu w Chinach nie są pełnym kosztem odbioru w innym kraju.",
  "Czytaj każde pole jako instrukcję dla agenta. Specyfikacja identyfikuje wariant, a uwagi zawierają tylko potrzebne dane. Unikaj zwrotów typu „najlepsza jakość”; podaj kod koloru, rozmiar, zestaw lub widoczną cechę. Jeśli koszt krajowy jest niejasny, postępuj według bieżącej instrukcji i pozwól agentowi go potwierdzić.",
  "Utwórz punkt kontroli dowodów magazynowych",
  "Po dostawie krajowej artykuł trafia do wskazanego magazynu. Oficjalna strona opisuje kontrolę, trzy do pięciu bezpłatnych zdjęć QC i 90 dni darmowego magazynowania. To bieżące warunki, nie stałe obietnice; sprawdź je na koncie. Gdy istnieją zdjęcia fizycznego produktu, oferta sprzedawcy nie jest już jedynym dowodem.",
  "Porównaj artykuł z zapisanym zamówieniem: kolor, model, ilość, widoczne wymiary, elementy, kształt i uszkodzenia. Jeśli brakuje ważnego szczegółu, sprawdź aktualne opcje zdjęć lub usługi przed akceptacją. Arkusz porządkuje linki i notatki QC, ale nie zastępuje oglądania zdjęć.",
  "Dopasuj artykuł do zapisanego ID i wariantu.","Sprawdź cały obiekt przed powiększaniem szczegółów.","Zapisz pytania, gdy zwrot lub wymiana mogą być jeszcze możliwe.","Nie myl czystego zdjęcia z dowodem materiału lub trwałości.",
  "Policz decyzję, nie tylko cenę",
  "Niska cena może nadal prowadzić do złego zakupu. Porównaj cenę, dostawę krajową, usługi, opakowanie i wysyłkę międzynarodową; mogą dojść podatki lub cło. Każda paczka jest inna, więc arkusz nie powinien podawać uniwersalnej ceny końcowej bez kraju, daty, trasy i założeń.",
  "Cena na liście to tylko jedna kolumna. Duże artykuły tworzą wagę gabarytową, sztywne opakowanie chroni, ale powiększa paczkę, a łączenie obniża opłaty bazowe, lecz może zmienić trasy. Właściwa paczka nie zawsze jest największa. Poczekaj na dane magazynu i porównaj bieżący kalkulator.",
  "Zachowaj mały ślad kontroli",
  "Dobry proces pozostaje prosty. Zapisz nazwę, URL, ID źródła, wariant, zaobserwowaną cenę, datę i notatkę. Po zakupie dodaj ID zamówienia, przyjęcie, wynik QC i paczkę. Powstaje użyteczna historia bez danych płatniczych, która ułatwia wyjaśnienie różnic obsłudze.",
  "Daty mają znaczenie, bo platformy i sprzedawcy się zmieniają. Link sprawdzony trzy miesiące temu nie jest równy dzisiejszemu. Stany, warianty i ceny mogą się zmienić. Odpowiedzialny poradnik pokazuje datę i wymaga ponownej kontroli zamiast uznawać każdy wiersz za zawsze bezpieczny, dostępny lub „najlepszy”.",
  "Stosuj powtarzalny proces pięciu kroków",
  "Zacznij od precyzyjnego wyszukiwania i zostaw wpisy zgodne z opisem. Otwórz cel, zapisz wariant, ID i widoczne warunki. Prześlij link i sprawdź cenę oraz dostawę krajową. Porównaj dowody magazynowe z zamówieniem. Na końcu użyj rzeczywistych danych, by zdecydować, które artykuły wysłać razem.",
  "Ta kolejność nie pozwala arkuszowi zastąpić oceny. Jest zgodna z procesem ACBuy: zamówienie z linku, odbiór, kontrola i magazynowanie, utworzenie paczki i wybór wysyłki. Platforma obsługuje agenta; ty zachowujesz ślad decyzji i ponownie sprawdzasz zmienne dane.",
  "Czy arkusz ACBuy jest oficjalnym katalogiem?","Niekoniecznie. To niezależny poradnik. Traktuj każdy wiersz jako drogę do aktualnego wpisu i sprawdź ofertę przed zamówieniem.",
  "Dlaczego cena w arkuszu może różnić się od zamówienia?","Ceny, warianty, dostawa krajowa i dostępność sprzedawców mogą się zmieniać. Pierwszeństwo ma strona na żywo i kontrola agenta.",
  "Co zapisać przed złożeniem zamówienia?","Zachowaj ID lub URL, dokładny wariant, ilość, cenę i mierzalne instrukcje. Nie zapisuj danych płatniczych we wspólnym arkuszu.",
  "Czy zdjęcie QC gwarantuje jakość?","Nie. Pokazuje widoczny stan i cechy, ale nie gwarantuje ukrytej konstrukcji, składu, dopasowania ani trwałości."
]);
